import { useCssElement } from 'react-native-css';
export function View(props) {
  return useCssElement(RNView, props, { className: 'style' });
}

// src/global.css
@layer theme {
  @theme {
    --color-canvas: #fffaf0;
    --color-ink: #0a0a0a;
    --spacing-md: 16px;
  }
}
// usage: className='bg-canvas text-ink p-md'

// screen.tsx
import { View, Text } from '@/tw';
<View className='flex-1 bg-canvas p-md'>
  <Text className='text-title-sm text-ink'>Title</Text>
</View>

const { withNativewind } = require('nativewind/metro');
module.exports = withNativewind(config, {
  globalClassNamePolyfill: false,
  typescriptEnvPath: 'nativewind-env.d.ts',
});

import { cssInterop } from 'nativewind';
cssInterop(TextInput, {
  className: { target: 'style', nativeStyleToProp: { textAlign: true } },
  placeholderClassName: { target: false, nativeStyleToProp: { color: 'placeholderTextColor' } },
});

import { remapProps } from 'nativewind';
remapProps(FlatList, {
  className: 'style',
  contentContainerClassName: 'contentContainerStyle',
  columnWrapperClassName: 'columnWrapperStyle',
  ListHeaderComponentClassName: 'ListHeaderComponentStyle',
});

withNativewind(config, {
  globalClassNamePolyfill: false,
  typescriptEnvPath: 'nativewind-env.d.ts',
  // experiments: { inlineAnimations: true } // Reanimated perf vs fast-refresh tradeoff
});

const themes = {
  brand: { light: vars({ '--color-primary': 'black' }), dark: vars({ '--color-primary': 'white' }) }
};
<View style={themes.brand[colorScheme]}>{children}</View>

function Row({ className, textClassName }) {
  return (
    <View className={className}>
      <Text className={textClassName}>Hi</Text>
    </View>
  );
}

remapProps(FlatList, {
  className: 'style',
  contentContainerClassName: 'contentContainerStyle',
  columnWrapperClassName: 'columnWrapperStyle',
  ListHeaderComponentClassName: 'ListHeaderComponentStyle',
  ListFooterComponentClassName: 'ListFooterComponentStyle',
});
<FlatList className='bg-canvas' contentContainerClassName='px-md pb-safe' />

const StyledCircle = cssInterop(Circle, {
  className: {
    target: 'style',
    nativeStyleToProp: { fill: true, stroke: true, strokeWidth: true },
  },
});
